const menuButton=document.querySelector('.menu-toggle');const menu=document.querySelector('.main-nav');
if(menuButton&&menu){menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')==='true';menuButton.setAttribute('aria-expanded',String(!open));menu.classList.toggle('open');document.body.classList.toggle('menu-open',!open)});menu.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{menu.classList.remove('open');menuButton.setAttribute('aria-expanded','false');document.body.classList.remove('menu-open')}));}
document.querySelectorAll('.accordion button').forEach(button=>button.addEventListener('click',()=>{const article=button.closest('article');const open=article.classList.toggle('open');button.setAttribute('aria-expanded',String(open))}));
const yearNode=document.getElementById('year');if(yearNode)yearNode.textContent=new Date().getFullYear();
const trackingForm=document.getElementById('tracking-form');if(trackingForm){trackingForm.addEventListener('submit',event=>{event.preventDefault();const service=document.getElementById('track-service').value;const type=document.getElementById('track-number-type')?.value;const ref=document.getElementById('track-ref').value.trim();const mobile=document.getElementById('track-mobile').value.replace(/\D/g,'');const out=document.getElementById('tracking-message');if(!service||!type||ref.length<5||mobile.length<10){out.textContent='Please select a service, reference type and enter a valid number and mobile number.';return}out.textContent='Demonstration only: connect this form to the secure production tracking database before deployment.'});}
const enquiryForm=document.getElementById('enquiry-form');if(enquiryForm){enquiryForm.addEventListener('submit',event=>{event.preventDefault();const out=document.getElementById('enquiry-message');if(!event.currentTarget.checkValidity()){event.currentTarget.reportValidity();out.textContent='Please complete all required fields.';return}out.textContent='Thank you. This demonstration form is ready for secure backend connection.';event.currentTarget.reset()});}
const crmServiceFilter=document.getElementById('crm-service-filter');const crmStatusFilter=document.getElementById('crm-status-filter');const crmRows=document.querySelectorAll('#crm-case-list tr');const crmEmpty=document.getElementById('crm-empty');function filterCrmCases(){if(!crmServiceFilter||!crmStatusFilter)return;let visible=0;crmRows.forEach(row=>{const serviceMatch=crmServiceFilter.value==='all'||row.dataset.service===crmServiceFilter.value;const statusMatch=crmStatusFilter.value==='all'||row.dataset.status===crmStatusFilter.value;const show=serviceMatch&&statusMatch;row.hidden=!show;if(show)visible++});if(crmEmpty)crmEmpty.hidden=visible!==0;}if(crmServiceFilter&&crmStatusFilter){crmServiceFilter.addEventListener('change',filterCrmCases);crmStatusFilter.addEventListener('change',filterCrmCases);filterCrmCases();}
const aiChatForm=document.getElementById('ai-chat-form');if(aiChatForm){aiChatForm.addEventListener('submit',async event=>{event.preventDefault();const input=document.getElementById('ai-message');const messages=document.getElementById('ai-messages');const status=document.getElementById('ai-chat-status');const message=input.value.trim();if(!message)return;messages.insertAdjacentHTML('beforeend','<div class="ai-message user"></div>');messages.lastElementChild.textContent=message;input.value='';status.textContent='Thinking...';try{const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message})});const result=await response.json();messages.insertAdjacentHTML('beforeend','<div class="ai-message assistant"></div>');messages.lastElementChild.textContent=result.reply||result.error||'Please contact our team directly.';status.textContent=result.configured===false?'AI provider is not configured; WhatsApp support remains available.':'';messages.scrollTop=messages.scrollHeight;}catch(error){messages.insertAdjacentHTML('beforeend','<div class="ai-message assistant">The assistant is unavailable in this preview. Please use WhatsApp or email support.</div>');status.textContent='';}});}
const agentRegisterForm=document.getElementById('agent-register-form');if(agentRegisterForm){agentRegisterForm.addEventListener('submit',event=>{event.preventDefault();const message=document.getElementById('agent-register-message');message.textContent='Registration received for manual review. Production approval will connect this form to the secure agency API.';agentRegisterForm.reset();});}
const locationNode=document.querySelector('.utility-group:first-child span');if(locationNode&&!document.getElementById('mumbai-time')){const timeNode=document.createElement('span');timeNode.id='mumbai-time';timeNode.setAttribute('aria-label','Current time in Mumbai');locationNode.insertAdjacentElement('afterend',timeNode);const updateMumbaiTime=()=>{timeNode.textContent=new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',hour12:true}).format(new Date())};updateMumbaiTime();setInterval(updateMumbaiTime,60000);}
const weatherNode=document.getElementById('mumbai-weather');if(weatherNode){const labels={0:'Clear',1:'Mostly clear',2:'Partly cloudy',3:'Cloudy',45:'Foggy',48:'Foggy',51:'Light drizzle',53:'Drizzle',55:'Drizzle',61:'Light rain',63:'Rain',65:'Heavy rain',80:'Showers',81:'Showers',82:'Heavy showers',95:'Thunderstorm',96:'Storm',99:'Storm'};const updateMumbaiWeather=async()=>{try{const response=await fetch('https://api.open-meteo.com/v1/forecast?latitude=19.0760&longitude=72.8777&current=temperature_2m,weather_code&timezone=Asia%2FKolkata');if(!response.ok)throw new Error('Weather unavailable');const data=await response.json();weatherNode.textContent='Mumbai '+Math.round(data.current.temperature_2m)+'°C · '+(labels[data.current.weather_code]||'Current conditions');}catch(error){weatherNode.textContent='Mumbai weather unavailable';}};updateMumbaiWeather();setInterval(updateMumbaiWeather,900000);}
const dashboardState=document.getElementById('agent-dashboard-state');if(dashboardState){fetch('/api/agency/applications',{credentials:'include'}).then(response=>{if(!response.ok)throw new Error('Not authenticated');return response.json()}).then(data=>{dashboardState.textContent='Live API connected';dashboardState.classList.add('live');const active=document.getElementById('agent-active-count');if(active)active.textContent=String(data.applications.filter(item=>!['completed','rejected'].includes(item.status)).length);const table=document.getElementById('agent-case-table');if(table&&data.applications.length){table.innerHTML='<div><strong>Recent passenger applications</strong><span>Live agency data</span></div>'+data.applications.slice(0,5).map(item=>'<div class="agent-case-row"><b>'+item.reference+'</b><span>'+item.service+'</span><span class="status-pill processing">'+item.status+'</span><span>'+item.passenger_count+' passengers</span></div>').join('')}}).catch(()=>{});}
const agentLoginForm=document.getElementById('agent-login-form');const agentLoginMessage=document.getElementById('agent-login-message');async function loadAgentDashboard(){const response=await fetch('/api/agency/applications',{credentials:'include'});if(!response.ok)throw new Error('Approved agency access required');const data=await response.json();const state=document.getElementById('agent-dashboard-state');if(state){state.textContent='Live API connected';state.classList.add('live');}const active=document.getElementById('agent-active-count');if(active)active.textContent=String(data.applications.filter(item=>!['completed','rejected'].includes(item.status)).length);const table=document.getElementById('agent-case-table');if(table&&data.applications.length){table.innerHTML='<div><strong>Recent passenger applications</strong><span>Live agency data</span></div>'+data.applications.slice(0,5).map(item=>'<div class="agent-case-row"><b>'+item.reference+'</b><span>'+item.service+'</span><span class="status-pill processing">'+item.status+'</span><span>'+item.passenger_count+' passengers</span></div>').join('');}}
if(agentLoginForm){agentLoginForm.addEventListener('submit',async event=>{event.preventDefault();agentLoginMessage.textContent='Signing in...';try{const login=await fetch('/api/login',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:document.getElementById('agent-login-email').value,password:document.getElementById('agent-login-password').value})});if(!login.ok)throw new Error('Login failed');const csrf=await fetch('/api/csrf',{credentials:'include'});window.agentCsrf=(await csrf.json()).csrf_token;await loadAgentDashboard();agentLoginMessage.textContent='Signed in. Live agency data loaded.';}catch(error){agentLoginMessage.textContent=error.message;}});}
const agentUploadForm=document.getElementById('agent-upload-form');if(agentUploadForm){agentUploadForm.addEventListener('submit',async event=>{event.preventDefault();const message=document.getElementById('agent-upload-message');const file=document.getElementById('agent-document-file').files[0];if(!file){message.textContent='Choose a PDF or image first.';return}message.textContent='Uploading securely...';const reader=new FileReader();reader.onload=async()=>{try{const result=await fetch('/api/documents',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json','X-CSRF-Token':window.agentCsrf||''},body:JSON.stringify({case_reference:document.getElementById('agent-document-reference').value,filename:file.name,content_base64:String(reader.result).split(',')[1]})});const response=await result.json();if(!result.ok)throw new Error(response.error||'Upload failed');message.textContent='Document uploaded for review.';agentUploadForm.reset();}catch(error){message.textContent=error.message;}};reader.readAsDataURL(file);});}
